#include "facts/generated/facts_data.hpp"

namespace nikos::facts::data {

const Fact kHumanFacts[kFactsPerCategory] = {
    {"human-001", "Języki migowe świata", "Języki migowe nie są takie same na całym świecie. Brytyjski i amerykański język migowy znacznie się różnią."},
    {"human-002", "Rozmowa gwizdem", "Na wyspie La Gomera można przekazać całe zdania gwizdem. Silbo Gomero zastępuje dźwięki hiszpańskich słów gwizdami."},
    {"human-003", "Ponad 800 języków", "W Papui-Nowej Gwinei używa się ponad 800 języków. To jeden z najbardziej różnorodnych językowo krajów świata."},
    {"human-004", "Trzy pisma w jednym zdaniu", "W Japonii w jednym zdaniu spotykają się trzy rodzaje pisma. To kanji, hiragana i katakana, używane do różnych celów."},
    {"human-005", "Północ zamiast lewa", "W australijskim Guugu Yimithirr mówi się „północ” zamiast „lewo”. Nawet położenie drobnych rzeczy opisuje się stronami świata."},
    {"human-006", "Hieroglify w obie strony", "Egipskie hieroglify można było czytać w obu kierunkach. Stronę czytania wskazywały twarze ludzi i zwierząt w znakach."},
    {"human-007", "Złote pęknięcia", "W Japonii pęknięć naprawionej ceramiki nie zawsze się ukrywa. W kintsugi podkreśla się je lakierem z drobinami złota."},
    {"human-008", "Radosny Dzień Zmarłych", "W Meksyku Día de Muertos łączy pamięć o zmarłych z barwnymi ołtarzami, kwiatami i muzyką. Rodziny przygotowują dary dla upamiętnienia bliskich."},
    {"human-009", "Kraj saun", "W Finlandii jest ponad trzy miliony saun. Sauna bywa miejscem odpoczynku i spotkań z innymi ludźmi."},
    {"human-010", "Wieża z ludzi", "W Katalonii powstają wielopiętrowe wieże z ludzi. Uczestnicy tradycji castells stoją sobie na ramionach."},
    {"human-011", "Wyspy z trzciny", "Na jeziorze Titicaca ludzie mieszkają na pływających wyspach. Lud Uros buduje je z trzciny totora, stale dokładając nowe warstwy."},
    {"human-012", "Malowanie ziemi", "W Indiach układa się na ziemi kolorowe wzory zwane rangoli. Powstają z proszków, piasku lub płatków kwiatów."},
    {"human-013", "Dwa tony naraz", "W mongolskim śpiewie gardłowym słychać dwa tony naraz. Niski dźwięk łączy się z wysoką melodią tworzoną jednym głosem."},
    {"human-014", "Obraz z kropek", "Puentylizm pozwala namalować obraz z maleńkich kropek. Oglądane z daleka kolory łączą się w oczach widza."},
    {"human-015", "Mandala z piasku", "Mnisi tybetańscy tworzą bardzo dokładne wzory z piasku. Gotowe mandale bywają zamiatane na znak przemijania."},
    {"human-016", "Teatr z cieni", "W Indonezji w tradycyjnym teatrze występują cienie lalek. Skórzane figurki porusza się przed podświetlonym ekranem."},
    {"human-017", "Kolorowe litery", "Dla niektórych ludzi litery i cyfry mają własne kolory. To synestezja, czyli łączenie różnych wrażeń zmysłowych."},
    {"human-018", "Wyobraźnia bez obrazów", "Nie każdy potrafi wyobrazić sobie obraz w głowie. To afantazja — myślenie bez tworzenia obrazów w umyśle."},
    {"human-019", "Twarz w drzewie", "Czasem w sękach drzewa dostrzegamy ludzką twarz. To pareidolia: mózg widzi znajomy wzór tam, gdzie go nie ma."},
    {"human-020", "Niewidoczna zmiana", "Można nie zauważyć dużej zmiany w oglądanym obrazie. Gdy uwaga jest zajęta, różnica łatwo nam umyka."},
    {"human-021", "Pamięć podczas snu", "Sen pomaga utrwalić to, czego nauczyliśmy się w dzień. Podczas odpoczynku mózg przetwarza nowe wspomnienia."},
    {"human-022", "Ludzka echolokacja", "Niektórzy ludzie potrafią rozpoznawać przeszkody po echu. Nasłuchują odbicia kliknięć wydawanych językiem."},
    {"human-023", "Samodzielne łaskotanie", "Samodzielne łaskotanie zwykle jest mniej odczuwalne. Mózg przewiduje własny dotyk i osłabia jego wrażenie."},
    {"human-024", "Mózg bez receptorów bólu", "Sama tkanka mózgowa nie ma receptorów bólu. Boleć mogą jednak otaczające ją opony mózgowe oraz niektóre naczynia krwionośne."},
    {"human-025", "Niewidzialna plamka", "W każdym oku jest mała ślepa plamka bez komórek światłoczułych. Mózg zwykle uzupełnia brak obrazu, więc jej nie zauważamy."},
    {"human-026", "Pismo kobiet nüshu", "W Chinach kobiety używały osobnego pisma o nazwie nüshu. Zapisywały nim listy, pieśni i historie swojego życia."},
    {"human-027", "Spółgłoski jak kliknięcia", "W języku xhosa niektóre spółgłoski brzmią jak mlaskanie językiem. Takie kliknięcia są częścią słów, a nie tylko odgłosami."},
    {"human-028", "Tajemnica języka baskijskiego", "Język baskijski nie ma potwierdzonych żyjących krewnych. Choć mówi się nim w Europie, nie należy do rodziny indoeuropejskiej."},
    {"human-029", "Bęben, który mówi", "W Afryce Zachodniej bębny potrafią naśladować ludzką mowę. Zmiana napięcia skóry zmienia wysokość dźwięku."},
    {"human-030", "Historie rysowane w piasku", "Na Vanuatu rysunki na piasku potrafią opowiadać historie. Wzory tworzy się jednym palcem, często bez odrywania go od ziemi."},
    {"human-031", "Trzynaście miesięcy", "W Etiopii rok ma trzynaście miesięcy. Dwanaście ma po 30 dni, a ostatni tylko pięć lub sześć."},
    {"human-032", "Wspólne robienie kimchi", "W Korei wiele rodzin przygotowuje jesienią zapasy kimchi. Zwyczaj kimjang łączy wspólną pracę z dzieleniem się jedzeniem."},
    {"human-033", "Nazwisko od imienia rodzica", "W Islandii nazwisko często powstaje od imienia matki lub ojca. Końcówka -son oznacza syna, a -dóttir córkę."},
    {"human-034", "Powitanie nosami", "Maorysi w Nowej Zelandii mogą witać gości, dotykając się nosami. To hongi, tradycyjny gest powitania i pokoju."},
    {"human-035", "Nowy Rok pełen wody", "W Tajlandii podczas Nowego Roku ludzie oblewają się wodą. Songkran symbolizuje oczyszczenie i życzenie pomyślności."},
    {"human-036", "Rysowanie gorącym woskiem", "W Indonezji wzory na tkaninach maluje się gorącym woskiem. W batiku wosk osłania wybrane miejsca przed farbą."},
    {"human-037", "Obraz malowany na wodzie", "W Turcji powstają obrazy malowane na powierzchni wody. W technice ebru barwniki przenosi się z wody na papier."},
    {"human-038", "Znaki ukryte w przysłowiach", "W Ghanie znaki adinkra zdobią ubrania i tkaniny. Wiele z tych symboli nawiązuje do przysłów i wartości."},
    {"human-039", "Polskie papierowe wycinanki", "W Łowiczu ozdoby wycina się nawet z wielu warstw papieru. Na Kurpiach powstają też symetryczne wzory z jednej kartki."},
    {"human-040", "Buty jako instrument", "We flamenco tancerz może wybijać rytm uderzeniami butów. Stopy stają się wtedy instrumentem obok gitary i dłoni."},
    {"human-041", "Usta oszukują słuch", "To, co widzimy na ustach, może zmienić usłyszany dźwięk. W efekcie McGurka ten sam głos brzmi inaczej przy innym obrazie."},
    {"human-042", "Gumowa ręka jak własna", "Można poczuć, że gumowa ręka jest naszą własną. Dzieje się tak przy równoczesnym dotykaniu jej i ukrytej ręki."},
    {"human-043", "Pałac pamięci", "Mistrzowie pamięci spacerują w wyobraźni po znanych miejscach. Rozmieszczają tam informacje, które chcą zapamiętać."},
    {"human-044", "Wspomnienie, którego nie było", "Człowiek może pamiętać coś, co nigdy się nie wydarzyło. Sugestywne pytania potrafią zniekształcić wspomnienia."},
    {"human-045", "Superrozpoznawacze twarzy", "Niektórzy ludzie rozpoznają twarze dużo lepiej niż inni. Superrozpoznawacze pomagają nawet analizować nagrania z kamer."},
    {"human-046", "Nurkujące kobiety z Jeju", "Na koreańskiej wyspie Jeju kobiety nurkują bez butli tlenowych. Haenyeo zbierają pod wodą małże i jeżowce."},
    {"human-047", "Dlaczego palce się marszczą?", "Palce marszczą się w wodzie nie tylko przez jej wchłanianie. Nerwy zwężają tam naczynia krwionośne i skóra się fałduje."},
    {"human-048", "Oko oddycha powietrzem", "Przezroczysta rogówka oka nie ma własnych naczyń krwionośnych. Tlen pobiera między innymi z powietrza przez warstwę łez."},
    {"human-049", "Brawa bez dyrygenta", "Brawa na widowni potrafią same zsynchronizować swój rytm. Ludzie zaczynają klaskać razem, choć nikt nimi nie dyryguje."},
    {"human-050", "Człowiek naprawdę świeci", "Ludzkie ciało naprawdę emituje bardzo słabe światło. Jest około tysiąc razy zbyt słabe, by zobaczyć je gołym okiem."},
    {"human-051", "Wspólny przodek", "Ludzie i współczesne szympansy mają wspólnego przodka. Ludzie nie wywodzą się od dzisiejszych szympansów."},
    {"human-052", "Wiele gatunków ludzi", "Homo sapiens nie był jedynym gatunkiem człowieka. W przeszłości żyli też neandertalczycy i denisowianie."},
    {"human-053", "Neandertalskie DNA", "Wiele osób poza Afryką ma niewielki udział DNA neandertalskiego. To ślad dawnych kontaktów między populacjami."},
    {"human-054", "Dwunożność przed wielkim mózgiem", "Dwunożność rozwinęła się u przodków ludzi przed znacznym wzrostem mózgu. Ewolucja nie przebiegała jednym krokiem."},
    {"human-055", "Lucy z Etiopii", "Szkielet Lucy ma ponad trzy miliony lat. Należy do gatunku Australopithecus afarensis."},
    {"human-056", "Narzędzia starsze od sapiens", "Kamienne narzędzia powstawały długo przed pojawieniem się Homo sapiens. Część ma ponad dwa miliony lat."},
    {"human-057", "Kolor skóry i Słońce", "Zróżnicowanie pigmentacji skóry wiąże się między innymi z promieniowaniem UV. To wynik długiej adaptacji populacji."},
    {"human-058", "Trawienie mleka", "U części dorosłych ludzi enzym laktaza pozostaje aktywny. Ta cecha upowszechniła się w niektórych populacjach pasterskich."},
    {"human-059", "Zmienne zęby mądrości", "Nie u każdego wyrastają wszystkie zęby mądrości. Ich liczba i rozwój są zróżnicowane."},
    {"human-060", "Przystosowanie do wysokości", "Populacje Tybetu i Andów wykształciły odmienne adaptacje do rozrzedzonego powietrza. Nie istnieje jedna droga przystosowania."},
    {"human-061", "Religie mają różne korzenie", "Nie wszystkie religie mają jednego założyciela ani jedną datę powstania. Wiele tradycji rozwijało się stopniowo."},
    {"human-062", "Religie monoteistyczne", "Judaizm, chrześcijaństwo i islam są religiami monoteistycznymi. Różnią się jednak tekstami i praktykami."},
    {"human-063", "Tradycje hinduistyczne", "Hinduizm obejmuje wiele szkół, bóstw i praktyk. Nie ma jednego założyciela wspólnego dla wszystkich nurtów."},
    {"human-064", "Buddyzm i cierpienie", "W centrum nauk buddyjskich stoją cierpienie i droga do jego ustania. Tradycje buddyjskie różnią się między sobą."},
    {"human-065", "Sikhizm w Pendżabie", "Sikhizm ukształtował się w Pendżabie pod koniec XV wieku. Jego pierwszym guru był Nanak."},
    {"human-066", "Szinto i kami", "W japońskiej tradycji szinto ważne są kami, związane z naturą i miejscami. Szinto nie ma jednego założyciela."},
    {"human-067", "Święta ziemia przodków", "W wielu rdzennych tradycjach konkretne miejsca mają znaczenie duchowe. Wierzenia i praktyki różnią się jednak między społecznościami."},
    {"human-068", "Kalendarze religijne", "Różne tradycje wyznaczają święta według innych kalendarzy. Stosuje się między innymi kalendarze księżycowe i słoneczne."},
    {"human-069", "Post w wielu tradycjach", "Post jest obecny w wielu religiach, ale ma różne zasady i znaczenia. Nie zawsze polega na całkowitym niejedzeniu."},
    {"human-070", "Pielgrzymowanie", "Pielgrzymki występują w wielu tradycjach religijnych. Mogą prowadzić do sanktuariów, rzek lub innych ważnych miejsc."},
    {"human-071", "Opowieści o stworzeniu", "Kultury świata mają różne opowieści o początkach świata. Takie mity nie są tym samym co modele naukowe."},
    {"human-072", "Rytuały przejścia", "W wielu kulturach obrzędy zaznaczają wejście w nowy etap życia. Mogą dotyczyć dorosłości, małżeństwa lub śmierci."},
    {"human-073", "Człowiek i ogień", "Kontrolowane używanie ognia było ważne dla dawnych ludzi. Dokładna data jego pierwszego opanowania pozostaje sporna."},
    {"human-074", "Skąd bierze się czkawka?", "Czkawka to odruch związany z nagłym skurczem przepony. Charakterystyczny dźwięk powstaje przy zamknięciu głośni."},
    {"human-075", "Nie każdy czuje gorzki smak", "Wrażliwość na niektóre gorzkie związki zależy częściowo od genów. Dlatego ten sam smak ludzie mogą odbierać inaczej."},
    {"human-076", "Po co nam gęsia skórka", "Gęsia skórka powstaje przez skurcz małych mięśni przy włosach. To pozostałość reakcji, która u futrzastych ssaków nastrosza sierść."},
    {"human-077", "Dlaczego ziewamy", "Ziewanie występuje u ludzi i wielu innych kręgowców. Jego dokładna funkcja nadal jest przedmiotem badań."},
    {"human-078", "Smak ma więcej wymiarów", "Język wykrywa między innymi smak słodki, słony i umami. Aromat potraw silnie zależy też od węchu."},
    {"human-079", "Czemu nie widzimy nosa", "Nos stale znajduje się w polu widzenia naszych oczu. Mózg zwykle ignoruje tę przewidywalną informację."},
    {"human-080", "Mózg zużywa energię", "Mózg dorosłego zużywa znaczną część energii spoczynkowej organizmu. Jest aktywny także podczas snu."},
    {"human-081", "Sen i zegar biologiczny", "Światło pomaga synchronizować dobowy rytm człowieka. Istotną rolę odgrywa niewielki obszar podwzgórza."},
    {"human-082", "Dlaczego mamy odciski", "Linie papilarne powstają przed urodzeniem i różnią się między palcami. Mogą wspomagać kontakt skóry z powierzchnią."},
    {"human-083", "Lewa i prawa półkula", "Półkule mózgu mają pewne wyspecjalizowane funkcje. Popularny podział na ludzi „lewo-” i „prawopółkulowych” jest uproszczeniem."},
    {"human-084", "Mózg przewiduje ruch", "Podczas chwytania kubka mózg szacuje potrzebną siłę. Aktualizuje ten szacunek na podstawie dotyku i doświadczenia."},
    {"human-085", "Skąd bierze się rumieniec", "Rumieniec to zmiana przepływu krwi w skórze twarzy. Może pojawiać się w reakcji na silne emocje."},
    {"human-086", "Czy człowiek jest rybą?", "Ludzie wywodzą się z dawnej linii ryb mięśniopłetwych. W klasyfikacji kladystycznej należymy do tej gałęzi ewolucyjnego drzewa życia."},
    {"human-087", "Nasza wspólna matka?", "„Mitochondrialna Ewa” oznacza wspólną przodkinię pewnej linii DNA. Nie była jedyną kobietą żyjącą w swoich czasach."},
    {"human-088", "Przodkowie z Afryki", "Najstarsze znane szczątki Homo sapiens pochodzą z Afryki. Rozwój naszego gatunku nie był pojedynczym prostym marszem."},
    {"human-089", "Dlaczego ludzie się różnią", "Większość ludzkiej zmienności genetycznej występuje wewnątrz populacji. Granice państw nie wyznaczają ostrych granic biologicznych."},
    {"human-090", "Dziecko uczy się języka", "Niemowlęta rozpoznają dźwiękowe wzorce mowy jeszcze przed wypowiadaniem słów. Kontakt z językiem kształtuje tę zdolność."},
    {"human-091", "Wspólna muzyka ludzi", "Muzyka występuje we wszystkich dobrze zbadanych społeczeństwach. Jej style i znaczenia bywają jednak bardzo różne."},
    {"human-092", "Wiele sposobów liczenia", "Systemy liczenia nie zawsze używały podstawy dziesiętnej. Babilończycy stosowali system sześćdziesiątkowy."},
    {"human-093", "Niewidoczne mikroby", "Na ludzkiej skórze i w jelitach żyją liczne mikroorganizmy. Ich społeczności tworzą mikrobiom."},
    {"human-094", "O co chodzi z placebo", "Oczekiwania i kontekst terapii mogą zmieniać odczuwanie objawów. Nie oznacza to, że placebo leczy każdą chorobę."},
    {"human-095", "Fantomowa kończyna", "Niektórzy ludzie nadal czują rękę lub nogę po jej amputacji. Mózg może zachowywać reprezentację utraconej kończyny przez wiele lat."},
    {"human-096", "Dlaczego śmiejemy się razem", "Śmiech często pojawia się podczas kontaktów społecznych. Może pomagać sygnalizować więź i intencje."},
    {"human-097", "Gesty pomagają mówić", "Ludzie spontanicznie gestykulują podczas rozmowy. Gesty mogą też wspierać myślenie i zapamiętywanie."},
    {"human-098", "Co to jest deja vu", "Déjà vu to wrażenie, że nowa sytuacja została już przeżyta. Badacze wiążą je z mechanizmami pamięci i znajomości."},
    {"human-099", "Ruch, którego nie ma", "Dwa nieruchome obrazy pokazane w odpowiedniej kolejności mogą dać wrażenie ruchu. To jedno ze zjawisk ruchu pozornego wykorzystywanych w animacji."},
    {"human-100", "Ciało ma własny kompas", "Propriocepcja pomaga wiedzieć, gdzie znajdują się nasze kończyny. Działa nawet wtedy, gdy nie patrzymy na ręce."},
};

}  // namespace nikos::facts::data
